// Callback for streaming responses.
// `callback_data` is a pointer to user-defined data passed to the stream
// function. `chunk` is the piece of text from the stream. It's only valid for
// the duration of the call. `is_final` is true if this is the last chunk in the
// stream. `error_msg` is a null-terminated string with an error message, or
// NULL on success.
public static class LiteRtLmStreamCallback extends FunctionPointer {
    static { Loader.load(); }
    /** Pointer cast constructor. Invokes {@link Pointer#Pointer(Pointer)}. */
    public    LiteRtLmStreamCallback(Pointer p) { super(p); }
    protected LiteRtLmStreamCallback() { allocate(); }
    private native void allocate();
    public native void call(Pointer callback_data, @Cast("const char*") BytePointer chunk,
                                       @Cast("bool") boolean is_final, @Cast("const char*") BytePointer error_msg);
}

